41	     1	import * as SecureStore from "expo-secure-store";
42	     2	import { useCallback, useEffect, useState } from "react";
43	     3	import { Platform } from "react-native";
44	     4	
45	     5	import { reportError } from "@/shared/utils/devLog";
46	     6	
47	     7	/**
48	     8	 * Device-bound app-lock state.
49	     9	 *
50	    10	 * The biometric lock is tied to this device's hardware and keychain, so it is
51	    11	 * persisted in secure device-local storage instead of the settings table.
52	    12	 * Backups therefore never carry the lock state to another device: each device
53	    13	 * arms its own lock.
54	    14	 */
55	    15	
56	    16	const BIOMETRIC_LOCK_KEY = "applock.biometric";
57	    17	
58	    18	type BiometricLockListener = (enabled: boolean) => void;
59	    19	
60	    20	// Module cache keeps consumers (gate, settings screens) in sync and lets the
61	    21	// lock gate mount with the correct armed state after bootstrap resolves it.
62	    22	let cachedEnabled: boolean | null = null;
63	    23	const listeners = new Set<BiometricLockListener>();
64	    24	
65	    25	function publish(enabled: boolean): void {
66	    26	  for (const listener of listeners) listener(enabled);
67	    27	}
68	    28	
69	    29	export async function getBiometricLockEnabled(): Promise<boolean> {
70	    30	  if (cachedEnabled !== null) return cachedEnabled;
71	    31	  if (Platform.OS === "web") return false;
72	    32	  try {
73	    33	    const value = await SecureStore.getItemAsync(BIOMETRIC_LOCK_KEY);
74	    34	    cachedEnabled = value === "true";
75	    35	    return cachedEnabled;
76	    36	  } catch {
77	    37	    return false;
78	    38	  }
79	    39	}
80	    40	
81	    41	export async function setBiometricLockEnabled(value: boolean): Promise<void> {
82	    42	  cachedEnabled = value;
83	    43	  publish(value);
84	    44	  if (Platform.OS === "web") return;
85	    45	  try {
86	    46	    if (value) {
87	    47	      await SecureStore.setItemAsync(BIOMETRIC_LOCK_KEY, "true");
88	    48	    } else {
89	    49	      await SecureStore.deleteItemAsync(BIOMETRIC_LOCK_KEY);
90	    50	    }
91	    51	  } catch (error) {
92	    52	    reportError("appLock:persist", error);
93	    53	  }
94	    54	}
95	    55	
96	    56	export function subscribeBiometricLock(listener: BiometricLockListener): () => void {
97	    57	  listeners.add(listener);
98	    58	  return () => {
99	    59	    listeners.delete(listener);
100	    60	  };
101	    61	}
102	    62	
103	    63	export interface BiometricLockSetting {
104	    64	  enabled: boolean;
105	    65	  setEnabled: (value: boolean) => void;
106	    66	}
107	    67	
108	    68	/** Tracks the device-bound lock state; starts synchronously once bootstrap has resolved it. */
109	    69	export function useBiometricLock(): BiometricLockSetting {
110	    70	  const [enabled, setEnabledState] = useState(() => cachedEnabled ?? false);
111	    71	
112	    72	  useEffect(() => {
113	    73	    let active = true;
114	    74	    if (cachedEnabled === null) {
115	    75	      getBiometricLockEnabled()
116	    76	        .then((value) => {
117	    77	          if (active) setEnabledState(value);
118	    78	        })
119	    79	        .catch(() => undefined);
120	    80	    }
121	    81	    const unsubscribe = subscribeBiometricLock((value) => {
122	    82	      if (active) setEnabledState(value);
123	    83	    });
124	    84	    return () => {
125	    85	      active = false;
126	    86	      unsubscribe();
127	    87	    };
128	    88	  }, []);
129	    89	
130	    90	  const setEnabled = useCallback((value: boolean) => {
131	    91	    void setBiometricLockEnabled(value);
132	    92	  }, []);
133	    93	
134	    94	  return { enabled, setEnabled };
135	    95	}
