142	     6	
143	     7	/**
144	     8	 * The device's owner-verification level: enrolled biometrics, a passcode-only
145	     9	 * screen lock, or nothing the OS could verify against. A failed probe reports
146	    10	 * "none" so the lock gate opens rather than trapping the user.
147	    11	 */
148	    12	export async function getEnrolledAuthLevel(): Promise<EnrolledAuthLevel> {
149	    13	  if (Platform.OS === "web") return "none";
150	    14	
151	    15	  try {
152	    16	    const level = await LocalAuthentication.getEnrolledLevelAsync();
153	    17	    if (level === LocalAuthentication.SecurityLevel.NONE) return "none";
154	    18	    if (level === LocalAuthentication.SecurityLevel.SECRET) return "passcode";
155	    19	    return "biometrics";
156	    20	  } catch {
157	    21	    return "none";
158	    22	  }
159	    23	}
