184	     1	import { createContext, useCallback, useContext, useEffect, useRef, useState } from "react";
185	     2	import { AppState, type AppStateStatus } from "react-native";
186	     3	
187	     4	import { analytics } from "@/config/analytics";
188	     5	import { authenticate, getEnrolledAuthLevel } from "./auth";
189	     6	
190	     7	const UNLOCK_REASON = "Unlock your entries";
191	     8	const BACKGROUND_LOCK_THRESHOLD_MS = 60 * 1000; // 1 minute in background before re-locking
192	     9	
193	    10	const AppLockedContext = createContext(false);
194	    11	
195	    12	export const AppLockedProvider = AppLockedContext.Provider;
196	    13	
197	    14	/**
198	    15	 * True while the app is locked. Native modals draw in their own window above the
199	    16	 * lock screen, so they must stop rendering while this holds. They deliberately
200	    17	 * stay up through brief inactive states: dismissing a modal there interrupts
201	    18	 * anything it presented (share sheet, permission alert) and resets its content.
202	    19	 */
203	    20	export function useAppLocked(): boolean {
204	    21	  return useContext(AppLockedContext);
205	    22	}
206	    23	
207	    24	/**
208	    25	 * Owns the app-lock gate:
209	    26	 *   - opens locked and prompts while the lock is enabled
210	    27	 *   - hides content whenever the app is not active; this renders from JS, so
211	    28	 *     the OS may take its app-switcher snapshot before the cover lands
212	    29	 *   - re-locks after > 60 seconds in background
213	    30	 *   - opens directly when the device has no unlock method left, so the user
214	    31	 *     is never trapped outside their data (the enabled preference is kept and
215	    32	 *     the lock resumes once a screen lock exists again)
216	    33	 */
217	    34	export function useAppLock(enabled: boolean) {
218	    35	  const [locked, setLocked] = useState(enabled);
219	    36	  const [prompting, setPrompting] = useState(false);
220	    37	  const [appState, setAppState] = useState<AppStateStatus>(AppState.currentState);
221	    38	
222	    39	  const lockedRef = useRef(locked);
223	    40	  const promptingRef = useRef(false);
224	    41	  const enabledRef = useRef(enabled);
225	    42	  const backgroundTimeRef = useRef<number | null>(null);
226	    43	
227	    44	  lockedRef.current = locked;
228	    45	  enabledRef.current = enabled;
229	    46	
230	    47	  const unlock = useCallback(async () => {
231	    48	    if (promptingRef.current || !lockedRef.current) return;
232	    49	
233	    50	    promptingRef.current = true;
234	    51	    setPrompting(true);
235	    52	
236	    53	    try {
237	    54	      if ((await getEnrolledAuthLevel()) === "none") {
238	    55	        // Nothing on the device can verify the owner; prompting could never
239	    56	        // succeed and reinstalling would destroy the local timeline.
240	    57	        analytics.capture("app_lock_bypassed");
241	    58	        setLocked(false);
242	    59	        return;
243	    60	      }
244	    61	
245	    62	      if (await authenticate(UNLOCK_REASON)) {
246	    63	        setLocked(false);
247	    64	      }
248	    65	    } finally {
249	    66	      promptingRef.current = false;
250	    67	      setPrompting(false);
251	    68	    }
252	    69	  }, []);
253	    70	
254	    71	  useEffect(() => {
255	    72	    if (!enabled) {
256	    73	      setLocked(false);
257	    74	      return;
258	    75	    }
259	    76	    // Cold start prompt
260	    77	    void unlock();
261	    78	  }, [enabled, unlock]);
262	    79	
263	    80	  useEffect(() => {
264	    81	    const subscription = AppState.addEventListener("change", (nextState: AppStateStatus) => {
265	    82	      setAppState(nextState);
266	    83	      if (!enabledRef.current) return;
267	    84	
268	    85	      if (nextState === "background") {
269	    86	        backgroundTimeRef.current = Date.now();
270	    87	      } else if (nextState === "active") {
271	    88	        if (backgroundTimeRef.current) {
272	    89	          const elapsed = Date.now() - backgroundTimeRef.current;
273	    90	          backgroundTimeRef.current = null;
274	    91	
275	    92	          if (elapsed > BACKGROUND_LOCK_THRESHOLD_MS) {
276	    93	            setLocked(true);
277	    94	            lockedRef.current = true;
278	    95	            void unlock();
279	    96	          }
280	    97	        }
281	    98	      }
282	    99	    });
283	   100	
284	   101	    return () => {
285	   102	      subscription.remove();
286	   103	    };
287	   104	  }, [unlock]);
288	   105	
289	   106	  // The re-lock decision lands in the same update as "active", so content never
290	   107	  // shows for a frame between the cover lifting and the lock screen appearing.
291	   108	  const contentHidden = enabled && (locked || appState === "inactive" || appState === "background");
292	   109	
293	   110	  return { locked, contentHidden, prompting, unlock };
294	   111	}
