299	     1	import * as Location from "expo-location";
300	     2	
301	     3	import type { EntryLocation } from "@/shared/types";
302	     4	
303	     5	const MAX_ATTEMPTS = 2;
304	     6	const RETRY_DELAY_MS = 1000;
305	     7	const LAST_KNOWN_MAX_AGE_MS = 10 * 60 * 1000;
306	     8	const LAST_KNOWN_MAX_ACCURACY_M = 2000;
307	     9	
308	    10	export const LOCATION_UNAVAILABLE = "Not available";
309	    11	
310	    12	// Cached for the app session; a fresh fix is only taken on refresh.
311	    13	let sessionPlace: EntryLocation | null = null;
312	    14	
313	    15	/**
314	    16	 * Normalizes geocoded address components into a single canonical format:
315	    17	 * "Locality, Region, Country" with consecutive and empty deduplication.
316	    18	 * e.g. "Siliguri, West Bengal, India", "Austin, Texas, United States"
317	    19	 */
318	    20	export function formatGeocodedAddress(
319	    21	  address: Location.LocationGeocodedAddress
320	    22	): string | undefined {
321	    23	  const getField = (val: string | null | undefined) =>
322	    24	    val && val.trim().length > 0 ? val.trim() : null;
323	    25	
324	    26	  const city = getField(address.city);
325	    27	  const district = getField(address.district);
326	    28	  const subregion = getField(address.subregion);
327	    29	  const street = getField(address.street);
328	    30	  const name = getField(address.name);
329	    31	  const region = getField(address.region);
330	    32	  const country = getField(address.country);
331	    33	
332	    34	  const locality = city || district || subregion || street || name;
333	    35	  const parts = [locality, region, country].filter(Boolean) as string[];
334	    36	  const unique = parts.filter((part, index) => part !== parts[index - 1]);
335	    37	
336	    38	  if (!unique.length) return undefined;
337	    39	  return unique.join(", ");
338	    40	}
339	    41	
340	    42	/**
341	    43	 * Returns the canonical display name for an EntryLocation.
342	    44	 * Used consistently across all surfaces: Timeline, View/Reader, Details modal, Memory, etc.
343	    45	 */
344	    46	export function locationPlaceTitle(location?: EntryLocation | null): string {
345	    47	  if (!location) return LOCATION_UNAVAILABLE;
346	    48	  if (location.name?.trim()) {
347	    49	    return location.name.trim();
348	    50	  }
349	    51	  return "Location";
350	    52	}
351	    53	
352	    54	/** Canonical coordinate string representation. */
353	    55	export function formatLocationCoordinates(location: EntryLocation): string {
354	    56	  return `${location.latitude.toFixed(4)}, ${location.longitude.toFixed(4)}`;
355	    57	}
356	    58	
357	    59	export function locationAccessibilityLabel(location: EntryLocation): string {
358	    60	  return `${locationPlaceTitle(location)}, ${formatLocationCoordinates(location)}`;
359	    61	}
360	    62	
361	    63	async function reverseGeocode(latitude: number, longitude: number): Promise<string | undefined> {
362	    64	  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
363	    65	    try {
364	    66	      const places = await Location.reverseGeocodeAsync({ latitude, longitude });
365	    67	      if (places && places.length > 0 && places[0]) {
366	    68	        const formatted = formatGeocodedAddress(places[0]);
367	    69	        if (formatted) return formatted;
368	    70	      }
369	    71	    } catch {
370	    72	      if (attempt < MAX_ATTEMPTS) {
371	    73	        await new Promise((resolve) => setTimeout(resolve, RETRY_DELAY_MS));
372	    74	      }
373	    75	    }
374	    76	  }
375	    77	  return undefined;
376	    78	}
377	    79	
378	    80	async function coordsToPlace(latitude: number, longitude: number): Promise<EntryLocation> {
379	    81	  const name = await reverseGeocode(latitude, longitude);
380	    82	  return { latitude, longitude, name };
381	    83	}
382	    84	
383	    85	async function readPosition(): Promise<Location.LocationObject | null> {
384	    86	  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
385	    87	    try {
386	    88	      return await Location.getCurrentPositionAsync({
387	    89	        accuracy: Location.Accuracy.Balanced,
388	    90	      });
389	    91	    } catch {
390	    92	      if (attempt < MAX_ATTEMPTS) {
391	    93	        await new Promise((resolve) => setTimeout(resolve, RETRY_DELAY_MS));
392	    94	      }
393	    95	    }
394	    96	  }
395	    97	
396	    98	  try {
397	    99	    return await Location.getLastKnownPositionAsync({
398	   100	      maxAge: LAST_KNOWN_MAX_AGE_MS,
399	   101	      requiredAccuracy: LAST_KNOWN_MAX_ACCURACY_M,
400	   102	    });
401	   103	  } catch {
402	   104	    return null;
403	   105	  }
404	   106	}
405	   107	
406	   108	/** The place cached for the current app session, if one was resolved already. */
407	   109	export function getCachedPlace(): EntryLocation | null {
408	   110	  return sessionPlace;
409	   111	}
410	   112	
411	   113	/**
412	   114	 * Resolves place label from GPS on explicit user action.
413	   115	 *
414	   116	 * The resolved place is cached for the app session: repeat taps return it
415	   117	 * instantly without another GPS fix or reverse-geocode. Pass `refresh: true`
416	   118	 * to bypass the cache and take a fresh fix (which updates the cache).
417	   119	 *
418	   120	 * Permission determines whether the app is allowed to access location.
419	   121	 * Compose determines whether the app should actually use it.
420	   122	 *
421	   123	 * `prompt: true` requests OS permission if not yet granted.
422	   124	 */
423	   125	export async function fetchPlace(
424	   126	  options: { prompt?: boolean; refresh?: boolean } = {}
425	   127	): Promise<EntryLocation | null> {
426	   128	  const { prompt = false, refresh = false } = options;
427	   129	
428	   130	  if (!refresh && sessionPlace) return sessionPlace;
429	   131	
430	   132	  let permission = await Location.getForegroundPermissionsAsync();
431	   133	
432	   134	  if (permission.status !== "granted") {
433	   135	    if (!prompt) return null;
434	   136	    if (permission.canAskAgain) {
435	   137	      permission = await Location.requestForegroundPermissionsAsync();
436	   138	    }
437	   139	    if (permission.status !== "granted") return null;
438	   140	  }
439	   141	
440	   142	  const position = await readPosition();
441	   143	  if (!position) return null;
442	   144	
443	   145	  const place = await coordsToPlace(position.coords.latitude, position.coords.longitude);
444	   146	  sessionPlace = place;
445	   147	  return place;
446	   148	}
