322	     3	/** Deterministic pseudo-waveform heights (0–1) from a seed string. */
323	     4	export function waveformHeights(seed: string, count = WAVEFORM_BAR_COUNT): number[] {
324	     5	  let hash = 0;
325	     6	  for (let i = 0; i < seed.length; i += 1) {
326	     7	    hash = (hash << 5) - hash + seed.charCodeAt(i);
327	     8	    hash |= 0;
328	     9	  }
329	    10	
330	    11	  const heights: number[] = [];
331	    12	  for (let i = 0; i < count; i += 1) {
332	    13	    hash = (hash * 1103515245 + 12345) | 0;
333	    14	    heights.push(0.18 + (Math.abs(hash) % 72) / 100);
334	    15	  }
335	    16	
336	    17	  return heights;
337	    18	}
338	    19	
339	    20	/** Normalize a dB metering value (typically -160…0) to 0–1. */
340	    21	export function meteringToLevel(metering?: number): number {
341	    22	  if (metering === undefined || !Number.isFinite(metering)) return 0.15;
342	    23	  const normalized = (metering + 60) / 60;
343	    24	  return Math.min(1, Math.max(0.12, normalized));
344	    25	}
345	    26	
346	    27	/** Build live waveform levels from metering, padding with a minimum height. */
347	    28	export function liveWaveformLevels(samples: number[], count = WAVEFORM_BAR_COUNT): number[] {
348	    29	  if (!samples.length) {
349	    30	    return Array.from({ length: count }, () => 0.15);
350	    31	  }
351	    32	
352	    33	  const levels: number[] = [];
353	    34	  const step = Math.max(1, samples.length / count);
354	    35	
355	    36	  for (let i = 0; i < count; i += 1) {
356	    37	    const index = Math.min(samples.length - 1, Math.floor(i * step));
357	    38	    levels.push(samples[index]);
358	    39	  }
359	    40	
360	    41	  return levels;
361	    42	}
